<template>
  <AppForm ref="form" :model="model" class="report-editor" data-screenshot-editor="own" @paste.capture="blockReportImages" @drop.capture="blockReportImages" @submit.prevent>
    <div class="report-editor__scroll" v-loading="loading">
      <table class="report-grid"><thead><tr><th class="index">序号</th><th class="types">任务/项目类型（可多选）</th><th class="order">订单号</th><th class="project">项目名称</th><th class="task">具体任务</th><th class="quantity">工作量</th><th class="unit">单位</th><th class="duration">耗时</th><th class="action"></th></tr></thead>
      <tbody><tr v-for="(row,index) in model.rows" :key="reportRowKey(row)" :class="{'is-system':row.source_type==='system_event','is-child':parentRowKey(row)}">
        <td class="index"><strong>{{outline[index]}}</strong><small v-if="parentRowKey(row)" class="child-label">└ 二级</small><small v-if="row.source_type==='system_event'" title="系统记录自动汇总">系统</small></td>
        <td><span v-if="parentRowKey(row)" class="inherited">↳ 类型随上级</span><template v-else><el-form-item :prop="`rows.${index}.display_metadata.report_types`" :rules="[{type:'array',required:!locked(row),min:1,message:'请选择类型',trigger:'change'}]"><el-cascader :show-all-levels="false" :model-value="row.display_metadata.report_types" :options="typeOptions" :props="{multiple:true,emitPath:false}" filterable collapse-tags collapse-tags-tooltip :disabled="locked(row)" :aria-label="`第${index+1}行任务类型`" @update:model-value="updateTypes(row,$event)"></el-cascader></el-form-item><el-form-item v-if="row.display_metadata.report_types.includes('其他项目')" :prop="`rows.${index}.display_metadata.custom_project_type`" :rules="[{required:true,whitespace:true,message:'填写具体项目类型',trigger:'blur'}]"><el-input v-model="row.display_metadata.custom_project_type" placeholder="具体项目类型" :disabled="locked(row)||!canAddProjectCategory" maxlength="80" @input="changed" /></el-form-item><el-form-item v-for="parent in customParents(row)" :key="parent" :prop="`rows.${index}.display_metadata.custom_work_types.${parent}`" :rules="[{required:true,whitespace:true,message:'请输入具体'+parent,trigger:'blur'}]"><el-input v-model="row.display_metadata.custom_work_types[parent]" :placeholder="'请输入具体'+parent" :aria-label="'具体'+parent" :disabled="locked(row)" maxlength="80" @input="changed" /></el-form-item></template></td>
        <td><el-form-item :prop="`rows.${index}.display_metadata.order_no`" :rules="[{required:!locked(row)&&requiresProjectIdentity(row),whitespace:true,message:'请填写订单号',trigger:'blur'}]"><ReadonlyField v-if="parentRowKey(row)" :model-value="row.display_metadata.order_no || '随上级'" source="auto" /><el-input v-else v-model="row.display_metadata.order_no" :aria-label="`第${index+1}行订单号`" :disabled="locked(row)" maxlength="100" @input="orderInput(row)" @blur="checkOrder(row)" @change="checkOrder(row)" @paste="paste($event,index,0)" /></el-form-item></td>
        <td><el-form-item :prop="`rows.${index}.task_name`" :rules="[{required:!locked(row)&&requiresProjectIdentity(row),whitespace:true,message:'请填写项目名称',trigger:'blur'}]"><span v-if="parentRowKey(row)" class="inherited">↳ 项目随上级</span><el-input v-else v-model="row.task_name" type="textarea" :autosize="{minRows:2,maxRows:5}" :aria-label="`第${index+1}行项目名称`" :disabled="locked(row)" maxlength="255" @input="changed" @paste="paste($event,index,1)" /></el-form-item></td>
        <td><el-form-item :prop="`rows.${index}.progress_content`" :rules="[{required:!locked(row),whitespace:true,message:'填写具体任务',trigger:'blur'}]"><el-autocomplete v-model="row.progress_content" type="textarea" :autosize="{minRows:2,maxRows:6}" :fetch-suggestions="suggest" :trigger-on-focus="true" :aria-label="`第${index+1}行具体任务`" :disabled="locked(row)" maxlength="10000" placeholder="填写或选择历史任务" @input="changed" @change="remember(row.progress_content)" @select="remember(row.progress_content);changed()" @paste="paste($event,index,2)" /></el-form-item><small v-if="row.result_content" class="old-result">原工作成果：{{row.result_content}}</small></td>
        <td><el-form-item :prop="`rows.${index}.display_metadata.quantity`" :rules="[{required:!locked(row),validator:(_rule,value,done)=>locked(row)?done():quantityRule(_rule,value,done),trigger:'blur'}]"><el-input v-model="row.display_metadata.quantity" inputmode="decimal" :aria-label="`第${index+1}行工作量`" :disabled="locked(row)" @input="changed" @paste="paste($event,index,3)" /></el-form-item></td>
        <td><el-form-item :prop="`rows.${index}.display_metadata.quantity_unit`" :rules="[{validator:(_rule,value,done)=>done(!locked(row)&&!value?.trim()?new Error('请选择单位'):undefined),trigger:'change'}]"><el-select v-model="row.display_metadata.quantity_unit" filterable allow-create default-first-option clearable :aria-label="`第${index+1}行单位`" :disabled="locked(row)" placeholder="选择/输入" @change="changed"><el-option v-for="unit in units" :key="unit" :value="unit" :label="unit==='其他'?'其他（填写单位）':unit" /></el-select></el-form-item><el-form-item v-if="row.display_metadata.quantity_unit==='其他'" :prop="`rows.${index}.display_metadata.quantity_unit_other`" :rules="[{required:true,whitespace:true,message:'填写具体单位',trigger:'blur'}]"><el-input v-model="row.display_metadata.quantity_unit_other" placeholder="具体单位" :disabled="locked(row)" @input="changed" /></el-form-item></td>
        <td><el-form-item :prop="`rows.${index}.duration_minutes`" :rules="[{required:!locked(row),validator:(_rule,value,done)=>done(!locked(row)&&!(Number(value)>0)?new Error('请选择耗时'):undefined),trigger:'change'}]"><el-select v-model="row.duration_minutes" filterable :aria-label="`第${index+1}行耗时`" :disabled="locked(row)" @change="changed"><el-option :value="0" label="未填写" /><el-option v-if="row.duration_minutes && !durationOptions.includes(row.duration_minutes)" :value="row.duration_minutes" :label="`${durationLabel(row.duration_minutes)}（${row.duration_minutes}分钟）`" /><el-option v-for="minutes in durationOptions" :key="minutes" :value="minutes" :label="durationLabel(minutes)" /></el-select></el-form-item></td>
        <td class="row-actions"><el-popover v-if="editable" trigger="click" placement="left" :width="250"><div class="child-actions"><span>在本项目下新增二级工作行</span><el-input-number v-model="childCount" :min="1" :max="100" :precision="0" :aria-label="`第${index+1}行下级行数`" /><el-button type="primary" @click="addChildren(row,childCount)">生成下级</el-button></div><template #reference><el-button link type="primary" :aria-label="`第${index+1}行新增下级`">新增下级</el-button></template></el-popover><el-button v-if="editable&&row.source_type==='manual'&&row.display_metadata?.source!=='consultation_handoff'" link type="danger" :aria-label="`删除第${index+1}行`" @click="remove(index)">删除</el-button></td>
      </tr><tr v-if="!model.rows.length"><td colspan="9" class="empty">暂无工作记录，点击“新增一行”填写。</td></tr></tbody></table>
    </div>
    <footer><template v-if="editable"><el-button @click="add()">＋ 新增一行</el-button><el-input-number v-model="addCount" :min="1" :max="100" :precision="0" :step="1" step-strictly aria-label="新增行数" /><el-button @click="add(addCount)">新增多行</el-button></template><span>合计 {{durationLabel(total)}}（{{total}}分钟）</span><small>Tab 切换单元格；支持从 Excel 粘贴文字；所有字段禁止截图。仅非项目工作免填订单号和项目名称。</small></footer>
  </AppForm>
</template>
<script setup>
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import ReadonlyField from '@/components/common/ReadonlyField.vue'
import {reportRowKey,parentRowKey,reportOutline,syncReportChildren,nestDuplicateOrder,appendChildRows,ensureReportKeys} from '@/utils/workReportHierarchy'
import {createDailyReportCategory} from '@/api/tasks'
import {matchesSearch} from '@/utils/searchMatching'
import {durationLabel,durationOptions,newReportRow,normalizeReportRow,updateRowTypes,validQuantity,buildWorkTypeOptions,defaultWorkCategories,appendReportRows,blockReportImages,requiresProjectIdentity,categoryValue} from '@/utils/workReportForm'
const props=defineProps({rows:{type:Array,default:()=>[]},editable:Boolean,loading:Boolean,categories:{type:Object,default:()=>defaultWorkCategories},canAddProjectCategory:Boolean,categoryStorageReady:Boolean,history:{type:Array,default:()=>[]}})
const emit=defineEmits(['dirty-change','remember','categories-change'])
const model=reactive({rows:[]}),form=ref(),dirty=ref(0)
const addCount=ref(5),childCount=ref(1)
const outline=computed(()=>reportOutline(model.rows))
const typeOptions=computed(()=>buildWorkTypeOptions(props.categories,model.rows).map(group=>({...group,children:group.children.map(option=>({...option,disabled:option.value==='其他项目'&&!props.canAddProjectCategory&&!model.rows.some(row=>row.display_metadata.custom_project_type)}))})))
const units=['个','份','页','字','次','其他']
watch(()=>props.rows,rows=>{model.rows=rows.map(row=>{const value=normalizeReportRow(row);value.display_metadata.custom_work_types={...(value.display_metadata.custom_work_types||{})};return value});ensureReportKeys(model.rows);syncReportChildren(model.rows);dirty.value=0},{immediate:true})
const total=computed(()=>model.rows.reduce((sum,row)=>sum+(Number(row.duration_minutes)||0),0))
const locked=row=>!props.editable||row.source_type==='system_event'
function changed(){if(!props.editable)return;syncReportChildren(model.rows);dirty.value++;emit('dirty-change',dirty.value)}
function customParents(row){return row.display_metadata.report_types.filter(value=>value.endsWith('::__custom__')).map(value=>value.split('::')[0])}
function updateTypes(row,types){if(locked(row)||types.length===row.display_metadata.report_types.length&&types.every(value=>row.display_metadata.report_types.includes(value)))return;row.display_metadata.custom_work_types||={};updateRowTypes(row,types);form.value?.clearValidate();changed()}
function remember(value){if(value?.trim())emit('remember',value.trim())}
function suggest(query,callback){callback(props.history.filter(value=>matchesSearch(value,query)).slice(0,30).map(value=>({value})))}
function quantityRule(_rule,value,done){done(value!==''&&value!=null&&validQuantity(value)?undefined:new Error('请填写非负数字工作量'))}
function add(count=1){if(!props.editable)return;try{appendReportRows(model.rows,count);changed()}catch(error){ElMessage.warning(error.message)}}
function remove(index){if(model.rows.some(row=>parentRowKey(row)===reportRowKey(model.rows[index]))){ElMessage.warning('请先删除该项目的下级工作行');return}model.rows.splice(index,1);changed()}
const orderTimers=new Map()
function orderInput(row){changed();clearTimeout(orderTimers.get(reportRowKey(row)));orderTimers.set(reportRowKey(row),setTimeout(()=>checkOrder(row),400))}
function checkOrder(row){clearTimeout(orderTimers.get(reportRowKey(row)));if(!model.rows.includes(row))return;if(nestDuplicateOrder(model.rows,row)){ElMessageBox.alert('同一个项目应当填写在下一级！','重复订单号',{confirmButtonText:'知道了'}).catch(()=>{});form.value?.clearValidate();changed()}}
onBeforeUnmount(()=>{for(const timer of orderTimers.values())clearTimeout(timer)})
function addChildren(row,count){try{appendChildRows(model.rows,row,count);changed();form.value?.clearValidate()}catch(error){ElMessage.warning(error.message)}}
function paste(event,index,column){
  if(!props.editable||blockReportImages(event))return
  const text=event.clipboardData?.getData('text/plain')||'';if(!text.includes('\t'))return
  event.preventDefault()
  const rows=text.replace(/\r/g,'').replace(/\n$/,'').split('\n').map(line=>line.split('\t'))
  for(let r=0;r<rows.length;r++){
    if(!model.rows[index+r])model.rows.push(newReportRow())
    const row=model.rows[index+r];if(locked(row))continue
    rows[r].forEach((value,c)=>{switch(column+c){case 0:if(parentRowKey(row))break;row.display_metadata.order_no=value.slice(0,100);break;case 1:if(parentRowKey(row))break;row.task_name=value.slice(0,255);break;case 2:row.progress_content=value.slice(0,10000);remember(value);break;case 3:row.display_metadata.quantity=value;break;case 4:row.display_metadata.quantity_unit=value;break;case 5:{const n=Number(value.replace(/分钟|小时/g,''));if(Number.isFinite(n))row.duration_minutes=Math.min(1440,Math.max(0,Math.round(n*(value.includes('小时')?60:1))));break}}})
  }
  for(const row of [...model.rows].reverse())if(nestDuplicateOrder(model.rows,row))ElMessage.info('同一个项目应当填写在下一级！')
  changed()
}
function getRows(){syncReportChildren(model.rows);model.rows.forEach(row=>remember(row.progress_content));return model.rows.map(row=>({...row,display_metadata:{...row.display_metadata}}))}
async function validate(){syncReportChildren(model.rows);await form.value.validate();for(const row of model.rows){if(props.canAddProjectCategory&&row.display_metadata.report_types.includes('其他项目')&&row.display_metadata.custom_project_type?.trim()!=='其他项目'){const name=row.display_metadata.custom_project_type.trim();try{const data=await createDailyReportCategory({parent:'项目工作',name});emit('categories-change',data);updateRowTypes(row,row.display_metadata.report_types.map(value=>value==='其他项目'?categoryValue('项目工作',name):value));delete row.display_metadata.custom_project_type}catch(error){ElMessage.error(error.detail||'保存自定义项目选项失败');throw error}}for(const parent of customParents(row)){const name=row.display_metadata.custom_work_types[parent].trim();let data;try{data=await createDailyReportCategory({parent,name})}catch(error){ElMessage.error(error.detail||'保存自定义工作选项失败');throw error}emit('categories-change',data);updateRowTypes(row,row.display_metadata.report_types.map(value=>value===`${parent}::__custom__`?categoryValue(parent,name):value))}delete row.display_metadata.custom_work_types}return true}
defineExpose({getRows,validate,add})
</script>
<style scoped>
.report-editor__scroll{overflow:auto;max-height:65vh;border:1px solid #dbe3ec;border-radius:6px}.report-grid{border-collapse:collapse;width:100%;min-width:1320px;table-layout:fixed}.report-grid th{position:sticky;top:0;z-index:2;background:#f1f5f9;color:#334155;text-align:left;padding:10px 8px;font-size:13px}.report-grid td{border:1px solid #e2e8f0;padding:5px;vertical-align:top;background:white}.report-grid .index{width:48px;text-align:center}.types{width:205px}.order{width:142px}.project{width:250px}.task{width:340px}.quantity{width:85px}.unit{width:100px}.duration{width:130px}.action{width:95px}.index small{display:block;color:#64748b;font-size:10px}.report-grid :deep(.el-form-item){margin-bottom:0}.report-grid :deep(.el-form-item.is-error){padding-bottom:18px}.report-grid :deep(.el-input__wrapper){box-shadow:none;padding:3px 5px;background:white}.report-grid :deep(.el-textarea__inner){box-shadow:none;padding:5px;resize:vertical}.report-grid :deep(.el-input__wrapper.is-focus),.report-grid :deep(.el-textarea__inner:focus){box-shadow:0 0 0 2px #409eff inset}.report-grid :deep(.el-select),.report-grid :deep(.el-cascader),.report-grid :deep(.el-autocomplete){width:100%}.is-system td,.is-system :deep(.el-textarea__inner),.is-system :deep(.el-input__wrapper){background:#f1f5f9}.old-result{display:block;color:#64748b;white-space:pre-wrap;padding:4px}.empty{padding:28px!important;text-align:left;color:#64748b}footer{display:flex;align-items:center;flex-wrap:wrap;gap:16px;padding:10px 0}footer span{font-weight:600}footer small{color:#64748b}
</style>

<style scoped>.category-form{display:flex;flex-direction:column;gap:12px}.category-form small{color:#64748b}footer :deep(.el-input-number){width:130px}</style>

<style scoped>.report-grid .is-child td{border-top-style:dashed;background:#eff6ff}.report-grid .is-child td:first-child{border-left:5px solid #409eff;padding-left:12px}.child-label{color:#2563eb!important;font-weight:600}.inherited{display:block;font-size:12px;color:#64748b;padding:12px 4px}.row-actions{white-space:normal}.row-actions .el-button{margin:3px 0}.child-actions{display:flex;flex-direction:column;gap:12px}</style>
<style scoped>.report-grid :deep(.field-readonly .el-input__wrapper){background:#f1f5f9}</style>
